import{_ as s,C as i,o as d,c as l,j as r,a as n,G as a,aj as o}from"./chunks/framework.BwH0p-pt.js";const b=JSON.parse('{"title":"Magic AI Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/configuration/magic-ai.md","filePath":"2.0/configuration/magic-ai.md","lastUpdated":1779777918000}'),p={name:"2.0/configuration/magic-ai.md"};function h(c,t,g,m,u,f){const e=i("ImagePopup");return d(),l("div",null,[t[0]||(t[0]=r("h1",{id:"magic-ai-configuration",tabindex:"-1"},[n("Magic AI Configuration "),r("a",{class:"header-anchor",href:"#magic-ai-configuration","aria-label":'Permalink to "Magic AI Configuration"'},"​")],-1)),t[1]||(t[1]=r("p",null,[r("strong",null,"Magic AI"),n(" is UnoPim's built-in layer for generating, enriching, and translating product and category content with Large Language Models (LLMs). Before you can use any AI feature — the Magic AI wand icons on product fields, the AI Agent Chat, auto-translation, or auto-enrichment — you must first configure Magic AI from the admin sidebar.")],-1)),a(e,{src:"/assets/2.0/images/configuration/AiConfiguration.png",alt:"Magic AI Configuration Overview"}),t[2]||(t[2]=o(`<h2 id="what-does-magic-ai-do" tabindex="-1">What does Magic AI do? <a class="header-anchor" href="#what-does-magic-ai-do" aria-label="Permalink to &quot;What does Magic AI do?&quot;">​</a></h2><p>Magic AI wires your UnoPim instance to one or more external AI providers (OpenAI, Anthropic, Gemini, Ollama, Groq, etc.) and exposes that power inside the PIM in four ways:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Where it appears in the UI</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Text generation</strong></td><td>Wand icon next to product/category text fields</td><td>Writes names, descriptions, SEO meta fields, category copy</td></tr><tr><td><strong>Image generation</strong></td><td>Wand icon next to image/gallery attributes</td><td>Creates product imagery from a text description</td></tr><tr><td><strong>Translation</strong></td><td>Automatic on product save, plus a bulk command</td><td>Translates locale-specific values across all configured locales</td></tr><tr><td><strong>Agentic PIM (AI Agent Chat)</strong></td><td>&quot;Open Agenting PIM&quot; button, bottom-right</td><td>Conversational assistant that calls 30+ PIM tools on your behalf</td></tr></tbody></table><p>All four share the same provider connections, prompt library, and system personality — so when you change Magic AI settings, every AI feature in UnoPim picks up the change.</p><h2 id="how-does-magic-ai-work" tabindex="-1">How does Magic AI work? <a class="header-anchor" href="#how-does-magic-ai-work" aria-label="Permalink to &quot;How does Magic AI work?&quot;">​</a></h2><p>The pipeline is the same for every AI feature:</p><ol><li><strong>You trigger a request</strong> — click a wand icon, save a product with auto-translate on, or send a chat message to the AI Agent.</li><li><strong>UnoPim assembles the input</strong> — it combines: <ul><li>The target entity&#39;s data (e.g., the product&#39;s name, attributes, category)</li><li>The matching <strong>Prompt</strong> from Magic AI → Prompts (with <code>@attribute</code> placeholders expanded)</li><li>The active <strong>System Prompt</strong> personality (tone, temperature, max tokens)</li></ul></li><li><strong>UnoPim forwards the request</strong> through the unified <strong>LaravelAiAdapter</strong> to the platform/model you selected in Magic AI → Settings.</li><li><strong>The provider responds</strong> with generated text, an image, or a translation.</li><li><strong>UnoPim applies the result</strong> — either directly into the field, into the database (after optional approval), or streamed back into the chat.</li></ol><p>Everything between step 2 and step 5 is configured from the four sub-pages described below: <strong>Platforms</strong>, <strong>Settings</strong>, <strong>Prompts</strong>, and <strong>System Prompts</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>API keys never appear in plain text. All provider credentials are stored in the database with <strong>encrypted credential storage</strong>, and the key is masked in the UI after you save it.</p></div><h2 id="the-magic-ai-menu" tabindex="-1">The Magic AI Menu <a class="header-anchor" href="#the-magic-ai-menu" aria-label="Permalink to &quot;The Magic AI Menu&quot;">​</a></h2><p>Expand <strong>Magic AI</strong> in the admin sidebar and you&#39;ll see four sub-menu items. Each one owns a specific slice of the AI configuration — together they give you complete control over <em>which provider runs, which models it uses, which instructions it follows, and which personality it speaks with</em>.</p><table tabindex="0"><thead><tr><th>Menu item</th><th>URL</th><th>What you configure here</th><th>When to visit</th></tr></thead><tbody><tr><td><strong>Platforms</strong></td><td><code>/admin/magic-ai/platforms</code></td><td>Provider connections — add an OpenAI / Anthropic / Gemini / Ollama / Groq account, paste its API key, and choose which of its models to enable.</td><td>First-time setup, rotating API keys, adding a new provider, enabling new models.</td></tr><tr><td><strong>Settings</strong></td><td><code>/admin/configuration/general/magic_ai</code></td><td>Per-capability routing — pick which Platform + Model handles Text Generation, Image Generation, Translation, and Agentic PIM. Also the home for the daily token budget, approval mode, and auto-enrichment switches.</td><td>Any time you want to change which provider runs a given feature, tune safety limits, or turn features on/off.</td></tr><tr><td><strong>Prompts</strong></td><td><code>/admin/magic-ai/prompts</code></td><td>Prompt templates — the instruction text Magic AI sends with every request, using <code>@attribute_code</code> placeholders that get replaced with real entity values.</td><td>Tailoring AI output to your brand voice, adding prompts for new attributes or categories, tweaking the default prompts.</td></tr><tr><td><strong>System Prompts</strong></td><td><code>/admin/magic-ai/system-prompts</code></td><td>Global AI personality — tone, temperature, max tokens. Only one is active at a time, so your whole catalog keeps a consistent voice.</td><td>Changing the overall tone (formal vs. casual, concise vs. descriptive), tuning creativity, capping response length.</td></tr></tbody></table><h3 id="how-the-four-menu-items-connect" tabindex="-1">How the four menu items connect <a class="header-anchor" href="#how-the-four-menu-items-connect" aria-label="Permalink to &quot;How the four menu items connect&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        ┌────────────────────────┐</span></span>
<span class="line"><span>        │   1. Platforms         │   ← add providers + models</span></span>
<span class="line"><span>        │   Provider + API key   │</span></span>
<span class="line"><span>        │   + enabled models     │</span></span>
<span class="line"><span>        └────────┬───────────────┘</span></span>
<span class="line"><span>                 │ feeds the dropdowns in</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>        ┌────────────────────────┐</span></span>
<span class="line"><span>        │   2. Settings          │   ← route each capability to a platform+model</span></span>
<span class="line"><span>        │   Text / Image /       │</span></span>
<span class="line"><span>        │   Translation /        │</span></span>
<span class="line"><span>        │   Agentic PIM          │</span></span>
<span class="line"><span>        └───┬──────┬──────┬──────┘</span></span>
<span class="line"><span>            │      │      │</span></span>
<span class="line"><span>            │      │      └── uses ──► 4. System Prompts  (global personality)</span></span>
<span class="line"><span>            │      │                    — one active at a time</span></span>
<span class="line"><span>            │      │</span></span>
<span class="line"><span>            │      └── uses ──► 3. Prompts  (per-entity, per-purpose templates)</span></span>
<span class="line"><span>            │                    — \`@placeholders\` filled from entity data</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>            └── keeps everything within ACL, budget, and approval-mode limits</span></span></code></pre></div><p><strong>Read top to bottom, you configure once, then use everywhere.</strong> A wand click on a product description, an auto-translated field, or a chat message to the AI Agent all follow the same path through these four menu items.</p><h3 id="minimum-setup-order" tabindex="-1">Minimum setup order <a class="header-anchor" href="#minimum-setup-order" aria-label="Permalink to &quot;Minimum setup order&quot;">​</a></h3><p>If you&#39;re configuring Magic AI for the first time, visit the menu items in this order:</p><ol><li><strong>Platforms</strong> — add at least one provider, paste the API key, enable the models you plan to use, and <strong>star one as the default</strong>.</li><li><strong>Settings</strong> — enable the capabilities you need (Text / Image / Translation / Agentic PIM) and pick a Platform + Model for each. Set the Daily Token Budget and Change Approval Mode while you&#39;re here.</li><li><strong>Prompts</strong> — review the shipped prompts; adjust or add your own so the AI writes in the voice your catalog expects.</li><li><strong>System Prompts</strong> — confirm the active personality matches the tone you want across the whole catalog. Enable a different one if needed.</li></ol><p>Once those four pages are saved, every Magic AI feature in the admin — wand icons, auto-translation, auto-enrichment, and the AI Agent Chat — is ready to use.</p><h2 id="platforms" tabindex="-1">Platforms <a class="header-anchor" href="#platforms" aria-label="Permalink to &quot;Platforms&quot;">​</a></h2><p>Navigate to <strong>Magic AI → Platforms</strong> to manage the AI provider connections that every Magic AI feature uses.</p>`,21)),a(e,{src:"/assets/2.0/images/magic-ai/ai-platforms.png",alt:"AI Platforms"}),t[3]||(t[3]=o('<h3 id="what-a-platform-is" tabindex="-1">What a &quot;Platform&quot; is <a class="header-anchor" href="#what-a-platform-is" aria-label="Permalink to &quot;What a &quot;Platform&quot; is&quot;">​</a></h3><p>A <em>Platform</em> is one configured provider connection: a provider (OpenAI, Anthropic, Gemini, Ollama, Groq, …), an API key, and the list of models you&#39;ve enabled from that provider. You can configure as many Platforms as you want — for example, one OpenAI platform for writing, one Gemini platform for translation, and one Ollama platform for on-prem workloads — and UnoPim will route each AI feature to the platform you assign.</p><h3 id="platforms-datagrid" tabindex="-1">Platforms datagrid <a class="header-anchor" href="#platforms-datagrid" aria-label="Permalink to &quot;Platforms datagrid&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Label</strong></td><td>The name you assigned to the platform configuration</td></tr><tr><td><strong>Provider</strong></td><td>The AI provider (OpenAI, Anthropic, Gemini, Ollama, Groq, etc.)</td></tr><tr><td><strong>Models</strong></td><td>The models enabled for this platform</td></tr><tr><td><strong>Default</strong></td><td>Whether this platform is the default (Yes/No)</td></tr><tr><td><strong>Status</strong></td><td>Enabled or Disabled</td></tr><tr><td><strong>Created At</strong></td><td>Date the platform was added</td></tr><tr><td><strong>Actions</strong></td><td>Star (set as default), Edit (pencil icon), Delete (trash icon)</td></tr></tbody></table><h3 id="adding-a-platform" tabindex="-1">Adding a Platform <a class="header-anchor" href="#adding-a-platform" aria-label="Permalink to &quot;Adding a Platform&quot;">​</a></h3><p>Click <strong>Add Platform</strong> in the top-right. A two-step modal titled <strong>&quot;Add AI Platform&quot;</strong> opens.</p><p><strong>Step 1 — pick the provider.</strong></p><p>The first screen of the modal only has one field:</p><ul><li>**Provider *** — dropdown listing every supported provider (OpenAI, Anthropic, Gemini, Ollama, Groq, etc.).</li></ul><p>Select a provider and click <strong>Save</strong>. The modal expands to show the rest of the fields.</p>',10)),a(e,{src:"/assets/2.0/images/magic-ai/add-platform.png",alt:"Add AI Platform — Step 1"}),t[4]||(t[4]=o(`<p><strong>Step 2 — fill in the provider-specific details.</strong></p><ul><li><strong>Label</strong> — Enter a descriptive name for this platform configuration (e.g., <em>&quot;OpenAI Production&quot;</em>, <em>&quot;Gemini Translation&quot;</em>). This name appears in the downstream dropdowns on Magic AI → Settings.</li><li><strong>API Key</strong> — Paste the API key from your provider account. It is encrypted on save and masked in the UI afterwards.</li><li><strong>Models</strong> — A multiselect listing the models available from the selected provider. Only the models you tick here appear in the Settings dropdowns.</li><li><strong>Status</strong> — Toggle to enable or disable the platform.</li></ul><p>Click <strong>Save</strong> to finish. The platform appears in the datagrid.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>API credentials are stored with encrypted credential storage for security. Your API keys are never stored in plain text.</p></div><h3 id="platform-actions" tabindex="-1">Platform Actions <a class="header-anchor" href="#platform-actions" aria-label="Permalink to &quot;Platform Actions&quot;">​</a></h3><ul><li><strong>Star icon</strong> — Sets the platform as the <strong>default</strong>. The default is what the system uses when a feature is set to <em>&quot;Use Default Platform&quot;</em>. Only one platform can be the default at a time.</li><li><strong>Pencil icon</strong> — Opens the edit modal to update the platform label, API key, models, or status.</li><li><strong>Trash icon</strong> — Deletes the platform configuration. This action cannot be undone.</li></ul><h3 id="how-platform-selection-flows-into-features" tabindex="-1">How platform selection flows into features <a class="header-anchor" href="#how-platform-selection-flows-into-features" aria-label="Permalink to &quot;How platform selection flows into features&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Platforms (provider + key + models)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Settings (pick platform + model per feature)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├─► Text Generation ──► Wand icons on text fields</span></span>
<span class="line"><span>        ├─► Image Generation ──► Wand icons on image/gallery fields</span></span>
<span class="line"><span>        ├─► Translation ──────► Auto-translate on save + bulk command</span></span>
<span class="line"><span>        └─► Agentic PIM ──────► AI Agent Chat</span></span></code></pre></div><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Navigate to <strong>Magic AI → Settings</strong> in the sidebar. This opens the configuration page at <code>/admin/configuration/general/magic_ai</code> with four sections — one per capability. For each capability you pick <strong>which Platform</strong> and <strong>which Model</strong> should handle it. Using different Platforms for different capabilities lets you optimize cost, speed, and quality independently.</p>`,10)),a(e,{src:"/assets/2.0/images/magic-ai/magic-ai-settings.png",alt:"Magic AI Settings"}),t[5]||(t[5]=o('<h3 id="_1-agentic-pim" tabindex="-1">1. Agentic PIM <a class="header-anchor" href="#_1-agentic-pim" aria-label="Permalink to &quot;1. Agentic PIM&quot;">​</a></h3><p>This section controls the <strong>AI Agent Chat</strong> (the conversational assistant) and the autonomous workflows it powers: auto-enrichment on product create, catalog quality monitoring, and the approval queue that sits in front of AI-proposed changes.</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enable AI Agent Chat</strong></td><td>Master switch for the &quot;Open Agenting PIM&quot; chat button. When off, the floating button is hidden and no one can converse with the agent.</td></tr><tr><td><strong>Max Agent Steps Per Turn</strong></td><td>How many tool calls the agent may chain together for a single user message (default: 5). Higher = more autonomy per turn; lower = tighter control and cheaper tokens.</td></tr><tr><td><strong>Daily Token Budget</strong></td><td>Hard daily cap on tokens spent by the agent (e.g., 500 000). When the cap is hit, the agent replies with a budget-exhausted notice until the next day.</td></tr><tr><td><strong>Auto-Enrichment on Product Create</strong></td><td>When enabled, every newly created product is queued for AI enrichment — missing descriptions, SEO fields, etc. are filled in automatically.</td></tr><tr><td><strong>Catalog Quality Monitor</strong></td><td>Runs a scheduled AI sweep that reports on missing, thin, or inconsistent data across the catalog.</td></tr><tr><td><strong>Confidence Threshold</strong></td><td>Minimum confidence score (default: 0.7 — &quot;Balanced&quot;) the AI must reach before a proposed change is applied. Below the threshold, changes are held for review.</td></tr><tr><td><strong>Change Approval Mode</strong></td><td>How AI-proposed changes land in your data: <em>Auto-apply</em>, <em>Confirm &amp; apply</em> (default — the AI proposes values, asks you, then executes), or <em>Manual review</em> (everything goes to the Approval Queue).</td></tr></tbody></table><h3 id="_2-text-generation" tabindex="-1">2. Text Generation <a class="header-anchor" href="#_2-text-generation" aria-label="Permalink to &quot;2. Text Generation&quot;">​</a></h3><p>This section controls the wand icons next to text fields (product name, descriptions, SEO meta fields, category copy). When a user clicks a wand icon, UnoPim sends the field&#39;s prompt to the Platform and Model configured here.</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enabled</strong></td><td>Toggle to enable or disable text generation across the admin.</td></tr><tr><td><strong>Default Platform</strong></td><td>Choose which Platform serves text requests. Pick <em>&quot;Use Default Platform&quot;</em> to follow the starred platform, or override with a specific one.</td></tr><tr><td><strong>Default Model</strong></td><td>The model used for text generation, drawn from the models enabled on the chosen Platform.</td></tr></tbody></table><h3 id="_3-image-generation" tabindex="-1">3. Image Generation <a class="header-anchor" href="#_3-image-generation" aria-label="Permalink to &quot;3. Image Generation&quot;">​</a></h3><p>This section controls the wand icons on Image and Gallery attributes. Only Platforms whose provider supports image generation (OpenAI / DALL-E, Gemini, xAI) are listed.</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enabled</strong></td><td>Toggle to enable or disable image generation.</td></tr><tr><td><strong>Default Platform</strong></td><td>The image-capable Platform to use.</td></tr><tr><td><strong>Default Model</strong></td><td>The specific image model (e.g., <code>dall-e-3</code>).</td></tr></tbody></table><h3 id="_4-translation" tabindex="-1">4. Translation <a class="header-anchor" href="#_4-translation" aria-label="Permalink to &quot;4. Translation&quot;">​</a></h3><p>Translation can run automatically whenever a product is saved, and can also be triggered in bulk via the translation command. Because translation tends to be high-volume, Magic AI lets you assign a <strong>different Platform</strong> — typically a cheaper or faster one — for this job alone.</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enabled</strong></td><td>Toggle to enable or disable AI-powered translation.</td></tr><tr><td><strong>Default Platform</strong></td><td>The Platform used for translation requests.</td></tr><tr><td><strong>Translation Model</strong></td><td>The specific model used for translation — independent of the text-generation model.</td></tr><tr><td><strong>Replace Existing Value</strong></td><td>On: re-translating overwrites existing locale values. Off: only empty locale fields are filled, preserving manual translations.</td></tr><tr><td><strong>Source Channel</strong></td><td>The channel whose values serve as the source-of-truth.</td></tr><tr><td><strong>Target Channel</strong></td><td>The channel that receives the translated values.</td></tr><tr><td><strong>Source Locale</strong></td><td>The locale to translate from (e.g., <code>en_US</code>).</td></tr><tr><td><strong>Target Locales</strong></td><td>Multi-select; choose every locale you want to auto-populate.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can assign a different (potentially cheaper or faster) AI provider specifically for translations, keeping your premium provider for content generation.</p></div><p>Click <strong>Save Configuration</strong> at the bottom of the page to apply all changes. Settings take effect immediately — no restart required.</p><h2 id="prompts" tabindex="-1">Prompts <a class="header-anchor" href="#prompts" aria-label="Permalink to &quot;Prompts&quot;">​</a></h2><p>Navigate to <strong>Magic AI → Prompts</strong> to manage the <strong>prompt templates</strong> that tell the AI what to produce. A prompt is the instruction sent with every generation request; it&#39;s where you bake in your brand voice, required structure, or catalog-specific rules.</p>',16)),a(e,{src:"/assets/2.0/images/magic-ai/prompts.png",alt:"Prompts"}),t[6]||(t[6]=o('<h3 id="how-prompts-work" tabindex="-1">How prompts work <a class="header-anchor" href="#how-prompts-work" aria-label="Permalink to &quot;How prompts work&quot;">​</a></h3><p>Each prompt is tied to an <strong>Entity Type</strong> (product or category) and a <strong>Purpose</strong> (Text Generation or Image Generation). At generation time, UnoPim:</p><ol><li>Picks the prompt that matches the entity and purpose.</li><li>Replaces every <code>@attribute_code</code> placeholder with the actual value from the entity.</li><li>Adds the active System Prompt personality on top.</li><li>Sends the combined instructions to the Platform/Model configured for that capability.</li></ol><p>So a prompt of <code>Write a product description for @name in the @color variant</code> becomes, at generation time, something like <code>Write a product description for Air Max 90 in the Blue variant</code>.</p><h3 id="prompts-datagrid" tabindex="-1">Prompts datagrid <a class="header-anchor" href="#prompts-datagrid" aria-label="Permalink to &quot;Prompts datagrid&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>The name of the prompt</td></tr><tr><td><strong>Prompt</strong></td><td>The prompt text with placeholders</td></tr><tr><td><strong>Entity Type</strong></td><td>The entity the prompt applies to (product or category)</td></tr><tr><td><strong>Purpose</strong></td><td>Whether the prompt is for Text Generation or Image Generation</td></tr><tr><td><strong>Created At</strong></td><td>Date the prompt was created</td></tr><tr><td><strong>Updated At</strong></td><td>Date the prompt was last modified</td></tr><tr><td><strong>Actions</strong></td><td>Edit (pencil icon), Delete (trash icon)</td></tr></tbody></table><h3 id="creating-a-prompt" tabindex="-1">Creating a Prompt <a class="header-anchor" href="#creating-a-prompt" aria-label="Permalink to &quot;Creating a Prompt&quot;">​</a></h3><p>Click the <strong>Create Prompt</strong> button to add a new prompt. Fill in:</p><ul><li><strong>Title</strong> — how it appears in the list.</li><li><strong>Prompt</strong> — the instruction text. Use <code>@attribute_code</code> placeholders for any value you want filled in from the entity.</li><li><strong>Entity Type</strong> — product or category.</li><li><strong>Purpose</strong> — Text Generation or Image Generation.</li></ul><h3 id="shipped-prompts" tabindex="-1">Shipped prompts <a class="header-anchor" href="#shipped-prompts" aria-label="Permalink to &quot;Shipped prompts&quot;">​</a></h3><p>UnoPim ships with <strong>18 preset prompts</strong>. Most target image generation (product photography styles) and a handful target text generation. All of them target <code>product</code> as the Entity Type. Examples you&#39;ll see in the list:</p><table tabindex="0"><thead><tr><th>Title</th><th>Purpose</th></tr></thead><tbody><tr><td>Packaging Mockup</td><td>Image Generation</td></tr><tr><td>Hero Banner Image</td><td>Image Generation</td></tr><tr><td>Multi-Angle Product</td><td>Image Generation</td></tr><tr><td>Flat Lay Composition</td><td>Image Generation</td></tr><tr><td>Product with Size Reference</td><td>Image Generation</td></tr><tr><td>Close-Up Detail Shot</td><td>Image Generation</td></tr><tr><td>Lifestyle Product Image</td><td>Image Generation</td></tr><tr><td>White Background Product Shot</td><td>Image Generation</td></tr><tr><td>Product Elevator Pitch</td><td>Text Generation</td></tr><tr><td>Product Brief</td><td>Text Generation</td></tr></tbody></table><p>Open <strong>Magic AI → Prompts</strong> to see the full list, edit any preset, or create new ones.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use attribute codes as placeholders (prefixed with <code>@</code>) in your prompts. The AI will replace them with actual values from the product or category being processed.</p></div><h2 id="system-prompts" tabindex="-1">System Prompts <a class="header-anchor" href="#system-prompts" aria-label="Permalink to &quot;System Prompts&quot;">​</a></h2><p>Navigate to <strong>Magic AI → System Prompts</strong> to configure the AI&#39;s <strong>personality</strong> — the tone, style, and generation parameters that sit underneath every prompt.</p>',16)),a(e,{src:"/assets/2.0/images/magic-ai/system-prompts.png",alt:"System Prompts"}),t[7]||(t[7]=o('<h3 id="how-a-system-prompt-differs-from-a-prompt" tabindex="-1">How a System Prompt differs from a Prompt <a class="header-anchor" href="#how-a-system-prompt-differs-from-a-prompt" aria-label="Permalink to &quot;How a System Prompt differs from a Prompt&quot;">​</a></h3><ul><li>A <strong>Prompt</strong> says <em>what</em> to write for a specific field (&quot;write a product description …&quot;).</li><li>A <strong>System Prompt</strong> says <em>how</em> to write — voice, tone, creativity, length. It&#39;s applied in front of every prompt, globally.</li></ul><p>Only <strong>one System Prompt is active at any time</strong>. Enabling a new one automatically disables the previous one, so the entire catalog keeps a consistent voice.</p><h3 id="system-prompts-datagrid" tabindex="-1">System Prompts datagrid <a class="header-anchor" href="#system-prompts-datagrid" aria-label="Permalink to &quot;System Prompts datagrid&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>The name of the system prompt</td></tr><tr><td><strong>Tone</strong></td><td>The conversational tone (e.g., Confident, Vivid, Brief)</td></tr><tr><td><strong>Max Tokens</strong></td><td>The maximum number of tokens for AI responses</td></tr><tr><td><strong>Temperature</strong></td><td>The creativity level (lower = more focused, higher = more creative)</td></tr><tr><td><strong>Status</strong></td><td>Enabled or Disabled</td></tr><tr><td><strong>Created At</strong></td><td>Date the system prompt was created</td></tr><tr><td><strong>Updated At</strong></td><td>Date the system prompt was last modified</td></tr><tr><td><strong>Actions</strong></td><td>Edit (pencil icon), Delete (trash icon)</td></tr></tbody></table><h3 id="preset-system-prompts" tabindex="-1">Preset System Prompts <a class="header-anchor" href="#preset-system-prompts" aria-label="Permalink to &quot;Preset System Prompts&quot;">​</a></h3><p>UnoPim ships with 10 preset System Prompts. All ship with <strong>Max Tokens = 1024</strong>; only Temperature differs. Only one System Prompt can be enabled at a time.</p><table tabindex="0"><thead><tr><th>Title</th><th>Tone</th><th>Temperature</th><th>Notes</th></tr></thead><tbody><tr><td>Authoritative Guide</td><td>Confident, assertive, instructional</td><td>0.65</td><td></td></tr><tr><td>Descriptive Storyteller</td><td>Vivid, rich, engaging</td><td>0.9</td><td></td></tr><tr><td>Concise Responder</td><td>Brief, to-the-point</td><td>0.5</td><td></td></tr><tr><td>Technical Expert</td><td>Precise, analytical</td><td>0.6</td><td></td></tr><tr><td>Casual Conversationalist</td><td>Informal, relaxed</td><td>0.75</td><td></td></tr><tr><td>Motivational Coach</td><td>Energetic, encouraging</td><td>0.85</td><td></td></tr><tr><td>Empathetic Listener</td><td>Warm, understanding</td><td>0.6</td><td></td></tr><tr><td>Witty Commentator</td><td>Clever, humorous</td><td>0.9</td><td></td></tr><tr><td>Professional Advisor</td><td>Formal, respectful</td><td>0.65</td><td></td></tr><tr><td>Friendly Assistant</td><td>Friendly, helpful, casual</td><td>0.7</td><td>Enabled by default</td></tr></tbody></table><h3 id="creating-a-system-prompt" tabindex="-1">Creating a System Prompt <a class="header-anchor" href="#creating-a-system-prompt" aria-label="Permalink to &quot;Creating a System Prompt&quot;">​</a></h3><p>Click the <strong>Create System Prompt</strong> button to define a new AI personality. Configure:</p><ul><li><strong>Title</strong> — shows in the datagrid.</li><li><strong>Tone description</strong> — plain-language description of the voice (the model reads this).</li><li><strong>Max Tokens</strong> — caps response length. Lower values = shorter output and lower cost.</li><li><strong>Temperature</strong> — 0.0–1.0. Low values keep answers tight and repeatable; high values add variety and flair.</li><li><strong>Status</strong> — enabling this one disables the currently-active prompt.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Only one system prompt can be active at a time. Enabling a new system prompt automatically disables the previously active one. Choose a system prompt that matches the tone you want across all AI-generated content.</p></div><h2 id="configuration-checklist" tabindex="-1">Configuration checklist <a class="header-anchor" href="#configuration-checklist" aria-label="Permalink to &quot;Configuration checklist&quot;">​</a></h2><p>Before you start using Magic AI features, make sure you&#39;ve done all four of these:</p><ol><li><strong>Magic AI → Platforms</strong> — Add at least one platform, paste an API key, enable the models you want, and <strong>star one as default</strong>.</li><li><strong>Magic AI → Settings</strong> — Enable the capabilities you need (Text / Image / Translation / Agentic PIM) and pick a Platform + Model for each.</li><li><strong>Magic AI → Prompts</strong> — Review the shipped prompts or create your own to match your brand voice.</li><li><strong>Magic AI → System Prompts</strong> — Confirm the active personality matches the tone you want across the catalog.</li></ol><p>Once these four pages are configured, every Magic AI feature — wand icons, the AI Agent Chat, auto-translation, and auto-enrichment — will work without further setup.</p>',16))])}const P=s(p,[["render",h]]);export{b as __pageData,P as default};
